          | |- ro_cells _ _ ?A _ => match goal with H : ro_cells _ _ A _ |- _ => exact H end
          | |- bytes_at _ ?M ?A _ => assert_fails (is_evar M); match goal with H : bytes_at _ M A _ |- _ => exact H end
